class ActivityChannelCommandTests {
 static Guid A=Guid.NewGuid(), B=Guid.NewGuid(), P=Guid.NewGuid(), C=Guid.NewGuid(); static int passed,failed;
 static void Assert(bool b,string m){if(!b)throw new Exception(m);} static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}
 static string Run(Fake s,string cmd,string p,Guid? actor=null){return ActivityChannelCommandPlugin.Run(s,actor??A,cmd,p);} static void Code(string s,string c){Assert(s.Contains("\"code\":\""+c+"\""),s);} static void Ok(string s){Assert(s.Contains("\"ok\":true"),s);} static string Create(string extra=""){return "{\"requestId\":\""+C+"\",\"content\":\"Hello\\nworld\""+extra+"}";} static string Change(){return "{\"id\":\""+P+"\",\"expectedRowVersion\":\"1\"}";}
 static int Occurrences(string s,string needle){return (s.Length-s.Replace(needle,"").Length)/needle.Length;}
 static string Discussion(string cmd,Guid post,Guid parent){return "{\"requestId\":\""+C+"\",\"postId\":\""+post+"\",\"content\":\"Reply\""+(cmd=="reply"?",\"parentId\":\""+parent+"\"":"")+"}";}
 static int Main(){
 Test("anonymous denied",()=>Code(Run(new Fake(),"post","{}",Guid.Empty),"unauthenticated"));
 Test("pending eligible contact creates server stamped post",()=>{var s=new Fake();Ok(Run(s,"post",Create()));Assert(s.Created!=null&&((EntityReference)s.Created["mss_author"]).Id==A,"author");Assert(!s.Created.Contains("createdon")&&!s.Created.GetAttributeValue<bool>("mss_ispinned"),"server fields");});
 Test("disabled inactive and missing identity denied",()=>{foreach(int flag in new[]{1,2,3}){var s=new Fake{Denied=flag};Code(Run(s,"post",Create()),"forbidden");}});
 Test("forged author pin timestamp rejected",()=>{foreach(string key in new[]{"author","isPinned","createdOn"})Code(Run(new Fake(),"post",Create(",\""+key+"\":\"forged\"")),"validation");});
 Test("text whitespace and length rejected",()=>{Code(Run(new Fake(),"post",Create().Replace("Hello\\nworld","   ")),"validation");Code(Run(new Fake(),"post",Create().Replace("Hello\\nworld",new string('x',8001))),"validation");Ok(Run(new Fake(),"post",Create().Replace("Hello\\nworld",new string('x',8000))));});
 Test("owner delete uses native concurrency",()=>{var s=new Fake();Ok(Run(s,"remove",Change()));Assert(s.Deleted.ConcurrencyBehavior==ConcurrencyBehavior.IfRowVersionMatches&&s.Deleted.Target.RowVersion=="1","conditional delete");});
 Test("nonowner denied and admin allowed",()=>{Code(Run(new Fake(),"remove",Change(),B),"forbidden");var s=new Fake{Admin=true};Ok(Run(s,"remove",Change(),B));Assert(s.AdminQuery,"actual site role");});
 Test("pin unpin concurrency and metadata",()=>{var s=new Fake{Admin=true};Ok(Run(s,"pin",Change()));Assert(s.Updated.ConcurrencyBehavior==ConcurrencyBehavior.IfRowVersionMatches&&s.Updated.Target.Contains("mss_pinnedon"),"conditional pin");Ok(Run(s,"unpin",Change()));Assert(s.Updated.Target["mss_pinnedon"]==null,"clear metadata");});
 Test("native races sanitized",()=>{var s=new Fake{Race=true};Code(Run(s,"remove",Change()),"conflict");});
 Test("deterministic replay and mismatch",()=>{var s=new Fake();Ok(Run(s,"post",Create()));var id=s.Created.Id;Ok(Run(s,"post",Create()));Assert(s.Creates==1&&s.Created.Id==id,"duplicate create");Code(Run(s,"post",Create().Replace("Hello","Changed")),"conflict");});
 Test("reply retains original anchor and immediate parent",()=>{var s=new Fake();Ok(Run(s,"reply","{\"requestId\":\""+Guid.NewGuid()+"\",\"postId\":\""+P+"\",\"parentId\":\""+C+"\",\"content\":\"Reply\"}"));Assert(((EntityReference)s.Created["mss_activitypost"]).Id==P&&((EntityReference)s.Created["mss_parentcomment"]).Id==C,"anchors");});
 Test("child parent rejected before create while legacy records remain readable",()=>{var s=new Fake();Guid child=Guid.NewGuid();s.AddComment(C,Guid.Empty);s.AddComment(child,C);Code(Run(s,"reply",Discussion("reply",P,child)),"validation");Assert(s.Creates==0&&s.Created==null,"child reply wrote a record");string result=Run(s,"comments","{\"postIds\":[\""+P+"\"],\"page\":1}");Ok(result);Assert(result.Contains(child.ToString())&&result.Contains("\"parentId\":\""+C+"\""),"legacy child association lost");});
 Test("legacy nested reply exact replay returns existing row but new request cannot create",()=>{
  var identity=new Fake();Ok(Run(identity,"reply",Discussion("reply",P,C)));Guid existingId=identity.Created.Id;
  var s=new Fake();Guid child=Guid.NewGuid();s.AddComment(C,Guid.Empty);s.AddComment(child,C);s.AddComment(existingId,child);
  s.Retrieve("mss_activitycomment",existingId,new ColumnSet())["mss_commenttext"]="Reply";
  string payload=Discussion("reply",P,child), result=Run(s,"reply",payload);Ok(result);
  Assert(result.Contains("\"id\":\""+existingId+"\"")&&result.Contains("\"parentId\":\""+child+"\""),"legacy replay returned different row");
  Assert(s.Creates==0&&s.Created==null,"legacy replay created duplicate");
  Code(Run(s,"reply",payload.Replace("\"requestId\":\""+C,"\"requestId\":\""+Guid.NewGuid())),"validation");
  Assert(s.Creates==0&&s.Created==null,"new nested request wrote a record");
 });
 Test("root supports multiple child replies with independent request identities",()=>{var s=new Fake();string p=Discussion("reply",P,C);Ok(Run(s,"reply",p));Ok(Run(s,"reply",p.Replace("\"requestId\":\""+C,"\"requestId\":\""+Guid.NewGuid())));Assert(s.Creates==2&&((EntityReference)s.Created["mss_parentcomment"]).Id==C,"multiple child replies");});
 Test("inactive root parent rejected before create",()=>{var s=new Fake();var parent=s.SeedComments(1)[0];parent["statecode"]=new OptionSetValue(1);Code(Run(s,"reply",Discussion("reply",P,parent.Id)),"not_found");Assert(s.Creates==0,"inactive parent wrote a record");});
 Test("cross post and cyclic ancestry rejected",()=>{foreach(bool cycle in new[]{false,true}){var s=new Fake{Cycle=cycle,Cross=!cycle};Code(Run(s,"reply","{\"requestId\":\""+Guid.NewGuid()+"\",\"postId\":\""+P+"\",\"parentId\":\""+C+"\",\"content\":\"Reply\"}"),"validation");}});
 Test("feed bounded ordered null regular and aggregate failure",()=>{var s=new Fake{CountFails=true};var r=Run(s,"feed","{\"phase\":\"pinned\",\"page\":1}");Ok(r);Assert(r.Contains("\"countUnavailable\":true")&&r.Contains("\"totalCount\":null"),r);var qs=s.Queries.Where(q=>q.EntityName=="mss_activitypost").ToArray();Assert(qs.Length==2&&qs[0].PageInfo.Count==20&&qs[1].PageInfo.Count==10,"stream bounds");Assert(qs[0].Orders[0].AttributeName=="mss_pinnedon"&&qs[1].Orders[0].AttributeName=="createdon","ordering");Assert(qs[1].Criteria.Filters.Any(f=>f.FilterOperator==LogicalOperator.Or),"null flag regular");});
 Test("strict page bounds and extra query URLs",()=>{Code(Run(new Fake(),"feed","{\"phase\":\"regular\",\"page\":2501}"),"validation");Code(Run(new Fake(),"feed","{\"phase\":\"regular\",\"page\":1,\"nextLink\":\"https://evil.invalid\"}"),"validation");Code(Run(new Fake(),"comments","{\"postIds\":["+string.Join(",",Enumerable.Repeat("\""+P+"\"",41))+"],\"page\":1}"),"validation");});
 Test("comments bounded active post join stable order",()=>{var s=new Fake();Ok(Run(s,"comments","{\"postIds\":[\""+P+"\"],\"page\":1}"));var q=s.Queries.Last();Assert(q.PageInfo.Count==100&&q.Orders.Count==2&&q.LinkEntities.Any(l=>l.LinkToEntityName=="mss_activitypost"),"comment query");Code(Run(s,"comments","{\"postIds\":[],\"page\":1}"),"validation");});

 Test("count isolated success and exact payload",()=>{var s=new Fake();var r=Run(s,"count","{}");Ok(r);Assert(r.Contains("\"totalCount\":1")&&s.Aggregates==1,r);Code(Run(new Fake(),"count","{\"page\":1}"),"validation");});
 Test("count native fault has no subsequent SDK operations",()=>{var s=new Fake{CountFails=true};Code(Run(s,"count","{}"),"unavailable");Assert(s.Aggregates==1&&s.AfterFault==0,"continued after native fault");});
 Test("feed never executes aggregate",()=>{var s=new Fake{CountFails=true};Ok(Run(s,"feed","{\"phase\":\"regular\",\"page\":1}"));Assert(s.Aggregates==0,"feed aggregate transaction");});
 Test("nonempty pinned page continuation then thirty row transition",()=>{var s=new Fake();s.SeedPosts(40,true);s.SeedPosts(25,false);var first=Run(s,"feed","{\"phase\":\"pinned\",\"page\":1}");Assert(Occurrences(first,"\"content\":")==20&&first.Contains("pinned:2"),first);var transition=Run(s,"feed","{\"phase\":\"pinned\",\"page\":2}");Assert(Occurrences(transition,"\"content\":")==30&&transition.Contains("regular:2"),transition);var second=Run(s,"feed","{\"phase\":\"regular\",\"page\":2}");Assert(Occurrences(second,"\"content\":")==10&&second.Contains("regular:3"),second);var last=Run(s,"feed","{\"phase\":\"regular\",\"page\":3}");Assert(Occurrences(last,"\"content\":")==5&&last.Contains("\"nextLink\":null"),last);});
 Test("regular null flags and stable tie ordering are returned",()=>{var s=new Fake();var a=s.SeedPosts(3,false);a[0].Attributes.Remove("mss_ispinned");a[1]["statecode"]=new OptionSetValue(1);var r=Run(s,"feed","{\"phase\":\"regular\",\"page\":1}");Assert(Occurrences(r,"\"content\":")==2&&r.Contains(a[0].Id.ToString()),r);var expected=new[]{a[0],a[2]}.OrderBy(e=>e.Id).ToArray();Assert(r.IndexOf(expected[0].Id.ToString())<r.IndexOf(expected[1].Id.ToString()),"tie ordering");});
 Test("nonempty comments paginate hundred with stable ties",()=>{var s=new Fake();var a=s.SeedComments(101);string payload="{\"postIds\":[\""+P+"\"],\"page\":1}";var r=Run(s,"comments",payload);Assert(Occurrences(r,"\"content\":")==100&&r.Contains("comments:2"),r);var expected=a.OrderBy(e=>e.Id).ToArray();Assert(r.IndexOf(expected[0].Id.ToString())<r.IndexOf(expected[1].Id.ToString()),"comment tie order");r=Run(s,"comments",payload.Replace(":1}",":2}"));Assert(Occurrences(r,"\"content\":")==1&&r.Contains("\"nextLink\":null"),r);});
 Test("ceiling MoreRecords is explicitly unavailable",()=>{foreach(string phase in new[]{"pinned","regular"})Code(Run(new Fake{ForceMore=true},"feed","{\"phase\":\""+phase+"\",\"page\":2500}"),"unavailable");Code(Run(new Fake{ForceMore=true},"comments","{\"postIds\":[\""+P+"\"],\"page\":2500}"),"unavailable");});
 Test("external identity allows pending actor",()=>{var s=new Fake{External=true};Ok(Run(s,"post",Create()));});
 Test("actor scoped request identity creates distinct posts",()=>{var s=new Fake();Ok(Run(s,"post",Create()));Guid first=s.Created.Id;Ok(Run(s,"post",Create(),B));Assert(s.Creates==2&&s.Created.Id!=first,"actor collision");});
 Test("comment replay checks text post and parent",()=>{var s=new Fake();string p=Discussion("comment",P,Guid.Empty);Ok(Run(s,"comment",p));Ok(Run(s,"comment",p));Assert(s.Creates==1,"comment duplicate");Code(Run(s,"comment",p.Replace("Reply","Changed")),"conflict");Guid other=Guid.NewGuid();s.AddPost(other);Code(Run(s,"comment",p.Replace(P.ToString(),other.ToString())),"conflict");var t=new Fake();Guid parent2=Guid.NewGuid();t.AddComment(parent2,Guid.Empty);p=Discussion("reply",P,C);Ok(Run(t,"reply",p));Ok(Run(t,"reply",p));Code(Run(t,"reply",p.Replace("\"parentId\":\""+C,"\"parentId\":\""+parent2)),"conflict");});
 Test("missing and excessive ancestry are rejected",()=>{Code(Run(new Fake(),"reply",Discussion("reply",P,Guid.NewGuid())),"validation");var s=new Fake();Guid parent=Guid.Empty;for(int i=0;i<101;i++){Guid id=Guid.NewGuid();s.AddComment(id,parent);parent=id;}Code(Run(s,"reply",Discussion("reply",P,parent)),"validation");});
 Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1; }
 class Fake:IOrganizationService {
 public int Denied,Creates,Aggregates,AfterFault;bool faulted;public bool External,ForceMore;public bool Admin,AdminQuery,Race,Cycle,Cross,CountFails;public Entity Created;public DeleteRequest Deleted;public UpdateRequest Updated;public List<QueryExpression> Queries=new List<QueryExpression>();Dictionary<Guid,Entity> rows=new Dictionary<Guid,Entity>();
 public Entity Retrieve(string name,Guid id,ColumnSet cols){if(faulted)AfterFault++;if(rows.ContainsKey(id))return rows[id];if(name=="contact"){var c=new Entity(name,id);c["statecode"]=new OptionSetValue(Denied==1?1:0);c["adx_identity_logonenabled"]=Denied!=2;c["adx_identity_username"]=Denied==3||External?null:"user";c["fullname"]="Member";return c;}if(id!=P&&id!=C)throw new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{ErrorCode=-2147220969});var e=new Entity(name,id){RowVersion="1"};e["statecode"]=new OptionSetValue(0);e["mss_author"]=new EntityReference("contact",A);e["mss_content"]="Existing";e["mss_commenttext"]="Existing";e["createdon"]=e["modifiedon"]=DateTime.UtcNow;e["mss_activitypost"]=new EntityReference("mss_activitypost",Cross?Guid.NewGuid():P);if(Cycle)e["mss_parentcomment"]=new EntityReference("mss_activitycomment",C);return e;}
 public EntityCollection RetrieveMultiple(QueryBase query){if(faulted)AfterFault++;var q=query as QueryExpression;if(q==null){Aggregates++;if(CountFails){faulted=true;throw new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{ErrorCode=-2147164125,Message="aggregate limit"});}var e=new Entity("count");e["total"]=new AliasedValue("mss_activitypost","mss_activitypostid",1);return new EntityCollection(new[]{e});}Queries.Add(q);if(q.EntityName=="adx_externalidentity")return new EntityCollection(External?new[]{new Entity("adx_externalidentity",Guid.NewGuid())}:new Entity[0]);if(q.EntityName=="contact"&&q.LinkEntities.Count==0){var c=new Entity("contact",A);c["fullname"]="Member";return new EntityCollection(new[]{c});}if(q.EntityName=="mss_activitypost"||q.EntityName=="mss_activitycomment"){var condition=q.Criteria.Conditions.FirstOrDefault(c=>c.AttributeName==q.EntityName+"id");if(condition!=null)return new EntityCollection(rows.ContainsKey((Guid)condition.Values[0])?new[]{rows[(Guid)condition.Values[0]]}:new Entity[0]);return PageRows(q);}if(q.EntityName=="contact"){var role=q.LinkEntities[0].LinkEntities[0];AdminQuery=role.LinkCriteria.Conditions.Any(c=>c.AttributeName=="powerpagesiteid")&&role.LinkCriteria.Conditions.Any(c=>c.AttributeName=="powerpagecomponentid");return new EntityCollection(Admin?new[]{new Entity("contact",A)}:new Entity[0]);}return new EntityCollection();}

 public void AddPost(Guid id){var e=new Entity("mss_activitypost",id){RowVersion="1"};e["statecode"]=new OptionSetValue(0);e["mss_author"]=new EntityReference("contact",A);e["mss_content"]="Post "+id;e["createdon"]=e["modifiedon"]=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);rows[id]=e;}
 public void AddComment(Guid id,Guid parent){var e=new Entity("mss_activitycomment",id);e["statecode"]=new OptionSetValue(0);e["mss_author"]=new EntityReference("contact",A);e["mss_activitypost"]=new EntityReference("mss_activitypost",P);e["mss_commenttext"]="Comment "+id;e["createdon"]=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);if(parent!=Guid.Empty)e["mss_parentcomment"]=new EntityReference("mss_activitycomment",parent);rows[id]=e;}
 public Entity[] SeedPosts(int n,bool pin){var list=new List<Entity>();for(int i=0;i<n;i++){Guid id=Guid.NewGuid();AddPost(id);rows[id]["mss_ispinned"]=pin;if(pin)rows[id]["mss_pinnedon"]=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);list.Add(rows[id]);}return list.ToArray();}
 public Entity[] SeedComments(int n){var list=new List<Entity>();for(int i=0;i<n;i++){Guid id=Guid.NewGuid();AddComment(id,Guid.Empty);list.Add(rows[id]);}return list.ToArray();}
 static object Value(Entity e,string attr){if(attr==e.LogicalName+"id")return e.Id;object v;e.Attributes.TryGetValue(attr,out v);if(v is OptionSetValue)return ((OptionSetValue)v).Value;if(v is EntityReference)return ((EntityReference)v).Id;return v;}
 static bool Match(Entity e,FilterExpression f){var checks=f.Conditions.Select(c=>{object v=Value(e,c.AttributeName);if(c.Operator==ConditionOperator.Null)return v==null;if(c.Operator==ConditionOperator.Equal)return object.Equals(v,c.Values[0]);if(c.Operator==ConditionOperator.In)return c.Values.Contains(v);throw new Exception("unsupported filter");}).Concat(f.Filters.Select(child=>Match(e,child)));return f.FilterOperator==LogicalOperator.Or?checks.Any(x=>x):checks.All(x=>x);}
 EntityCollection PageRows(QueryExpression q){IEnumerable<Entity> all=rows.Values.Where(e=>e.LogicalName==q.EntityName&&Match(e,q.Criteria));IOrderedEnumerable<Entity> ordered=null;foreach(var order in q.Orders){Func<Entity,object> key=e=>Value(e,order.AttributeName);ordered=ordered==null?(order.OrderType==OrderType.Ascending?all.OrderBy(key):all.OrderByDescending(key)):(order.OrderType==OrderType.Ascending?ordered.ThenBy(key):ordered.ThenByDescending(key));}var list=(ordered??all).ToArray();int skip=(q.PageInfo.PageNumber-1)*q.PageInfo.Count;return new EntityCollection(list.Skip(skip).Take(q.PageInfo.Count).ToArray()){MoreRecords=ForceMore||list.Length>skip+q.PageInfo.Count};}
 public Guid Create(Entity e){Creates++;Created=e;var persisted=new Entity(e.LogicalName,e.Id){RowVersion="1"};foreach(var kv in e.Attributes)persisted[kv.Key]=kv.Value;persisted["statecode"]=new OptionSetValue(0);persisted["createdon"]=persisted["modifiedon"]=DateTime.UtcNow;rows[e.Id]=persisted;return e.Id;}
 public OrganizationResponse Execute(OrganizationRequest r){if(Race)throw new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{ErrorCode=-2147088254});Deleted=r as DeleteRequest;Updated=r as UpdateRequest;return new OrganizationResponse();}public void Update(Entity e){throw new Exception("unconditional update");}public void Delete(string n,Guid id){throw new Exception("unconditional delete");}public void Associate(string n,Guid id,Relationship r,EntityReferenceCollection e){throw new NotImplementedException();}public void Disassociate(string n,Guid id,Relationship r,EntityReferenceCollection e){throw new NotImplementedException();}
 }
